head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf10003";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_attrReals();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf10003.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "iframe_16", attr: "src", fn: function () { return String((dma_pageContext.get("tocUrl") ?? "")); } },
        { childId: "iframe_17", attr: "src", fn: function () { return "/dsclproc/JLDSTF10005_toc.jsp?body_url=" + String((dma_pageContext.get("tocUrl") ?? "")) + "&acpt_no=" + String((dma_pageContext.get("acptNo") ?? "")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_19_onclick
 * @description 「close」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_19_onclick = function(e){
    try {
        scwin.displayToc('close')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf10003.img_19_onclick' }); }
};

/**
 * @method
 * @name img_28_onclick
 * @description img_28 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_28_onclick = function(e){
    try {
        scwin.displayToc('open')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf10003.img_28_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkToc
 * @description check Toc 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkToc = function () {
    const isToc = 'null';
    const isIFRS = 'null';
    if (isToc === "Y" || isIFRS === "Y") {
        scwin.displayToc('open');
    } else {
        scwin.displayToc('close');
    }
};

/**
 * @method
 * @name displayToc
 * @description display Toc 처리
 * @param {*} command command
 * @returns {void}
 * @hidden N
 */
scwin.displayToc = function (command) {
    if (command === "close") {
        $c.util.getComponent("tocTd").width = "16";
        $c.util.getComponent("openToc").hide();
        $c.util.getComponent("closeToc").show();
    } else {
        if (command === "open") {
            $c.util.getComponent("tocTd").width = "210";
            $c.util.getComponent("openToc").show();
            $c.util.getComponent("closeToc").hide();
        }
    }
};
